import { useState, useMemo, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Newspaper, Clock, RefreshCw, Calendar } from 'lucide-react';
import { MOCK_NEWS_GROUPS, type INews } from '@/data/news';
import { getDailyIndex, getUpdateLabel, formatRelativeTime } from '@/lib/date-utils';
import type { ThemeConfig, FestivalBadge } from '@/lib/theme';
import { toast } from 'sonner';
import api from '@/lib/api';
import { fetchWithCache, formatCacheTime, DEFAULT_TTL } from '@/lib/cache';
import CollapsibleSection from '@/components/CollapsibleSection';

// 为新闻生成带相对时间的条目
interface NewsWithRelTime extends INews {
  relTime: string;
  dayIndex: number;
}

function buildDailyNews(baseNews: INews[], today: Date): NewsWithRelTime[] {
  const total = baseNews.length;
  const timePool = ['08:00', '08:30', '09:00', '09:15', '09:30', '10:00', '10:30', '11:00', '11:30', '13:00', '14:00', '15:00', '15:30', '16:00', '17:00', '18:30', '20:00'];
  const maxDays = 3;
  
  return baseNews.map((n, idx) => {
    const dayIndex = Math.min(maxDays, Math.floor((idx / Math.max(1, total)) * (maxDays + 1)));
    const timeIdx = (idx * 3 + 5) % timePool.length;
    const timeOfDay = timePool[(timePool.length - 1 - timeIdx + timePool.length) % timePool.length];
    const relTime = formatRelativeTime(dayIndex, timeOfDay, today);
    return { ...n, relTime, dayIndex };
  });
}

const COUNTRIES = [
  { key: 'all', label: '全部', flag: '🌍' },
  { key: '美国', label: '美国', flag: '🇺🇸' },
  { key: '日本', label: '日本', flag: '🇯🇵' },
  { key: '泰国', label: '泰国', flag: '🇹🇭' },
  { key: '中国', label: '中国', flag: '🇨🇳' },
] as const;

export default function NewsPage() {
  const { theme } = useOutletContext<{ theme: ThemeConfig; festival: FestivalBadge }>();
  const [activeCountry, setActiveCountry] = useState<string>('all');
  const [newsData, setNewsData] = useState<INews[]>([]);
  const [dataSource, setDataSource] = useState<'api' | 'mock'>('mock');
  const [loading, setLoading] = useState(true);
  const today = useMemo(() => new Date(), []);

  // ===== 折叠面板手风琴状态 =====
  const [expandedId, setExpandedId] = useState<string>('header');
  function toggleSection(id: string) {
    setExpandedId((prev) => (prev === id ? '' : id));
  }

  const [updateTime, setUpdateTime] = useState('');

  // 从 mock 取初始兜底数据
  const fallbackNews = useMemo<INews[]>(() => {
    const idx = getDailyIndex(MOCK_NEWS_GROUPS.length, today);
    return MOCK_NEWS_GROUPS[idx];
  }, [today]);

   // 加载真实新闻 API（force=true 强制刷新）
   const loadNews = async (showToast = false, force = false) => {
     try {
       const result = await fetchWithCache<any>('news:global', '/news', {
         ttl: DEFAULT_TTL,
         force,
       });
        if (result?.data?.items?.length > 0) {
          const items = result.data.items.map((item: any) => {
            if (item.source && item.source.trim()) return item;
            const summary = item.summary || '';
            const m = summary.match(/[（(]来源[：:]\s*([^）)\n]+)[）)]/) || summary.match(/来源[：:]\s*([^\n，。、]+)/);
            return { ...item, source: m ? m[1].trim() : '跨境资讯' };
          });
          setNewsData(items);
         setDataSource('api');
         setUpdateTime(formatCacheTime(result.timestamp));
         if (showToast) toast.success(force ? '资讯已刷新' : '资讯已更新');
         return;
       }
     } catch {
       // 失败用兜底
     }
    setNewsData(fallbackNews);
    setDataSource('mock');
    if (showToast) toast.info('已显示本地资讯');
  };

  useEffect(() => {
    let cancelled = false;
    setNewsData(fallbackNews);
    loadNews().finally(() => {
      if (!cancelled) setLoading(false);
    });
    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fallbackNews]);

  const dailyNews = useMemo<NewsWithRelTime[]>(() => {
    return buildDailyNews(newsData, today);
  }, [newsData, today]);

  function handleRefresh() {
    loadNews(true, true);
  }

  const filteredNews = useMemo(() => {
    if (activeCountry === 'all') return dailyNews;
    return dailyNews.filter(n => n.country === activeCountry);
  }, [dailyNews, activeCountry]);

  const customsKeywords = ['海关', '关税', '进出口', '跨境', '清关', '监管'];
  const isCustomsNews = (n: INews) => {
    if (n.tag === '海关') return true;
    for (const kw of customsKeywords) {
      if (n.title?.includes(kw)) return true;
      if (n.summary?.includes(kw)) return true;
    }
    return false;
  };

  const customsNews = useMemo(() => {
    const fromDaily = dailyNews.filter(n => isCustomsNews(n));
    if (fromDaily.length >= 6) return fromDaily;
    const mockCustoms = fallbackNews.filter(n => isCustomsNews(n));
    const seen = new Set(fromDaily.map(n => n.id));
    const supplement = mockCustoms.filter(n => !seen.has(n.id)).slice(0, 6 - fromDaily.length);
    const merged = [...fromDaily, ...buildDailyNews(supplement, today)];
    return merged.slice(0, 6);
  }, [dailyNews, fallbackNews, today]);

  return (
    <div className="space-y-3">
      {/* Header */}
      <CollapsibleSection
        title="新闻资讯"
        subtitle="NEWS FEED · 今日要闻速览"
        summary={`${dailyNews.length} 条资讯 · ${customsNews.length} 条海关要闻`}
        badge={dataSource === 'api' ? '实时' : '本地'}
        badgeColor={dataSource === 'api' ? 'success' : 'info'}
        theme={theme}
        expanded={expandedId === 'header'}
        onToggle={() => toggleSection('header')}
        icon={<Newspaper className="size-5" />}
        className="!shadow-md"
        headerExtra={
          <button
            onClick={handleRefresh}
            className="text-xs px-2 py-1 rounded-full flex items-center gap-1 transition-colors"
            style={{
              backgroundColor: theme.primaryLight ? theme.primaryLight + '80' : 'hsl(226 100% 96%)',
              color: theme.primary,
            }}
          >
            <RefreshCw className={`size-3 ${loading ? 'animate-spin' : ''}`} />
            刷新
          </button>
        }
      >
        <div
          className="p-5 text-white rounded-xl"
          style={{
            background: `linear-gradient(135deg, ${theme.primary}, ${theme.primaryLight})`,
          }}
        >
          <div className="flex items-start gap-3 flex-1 min-w-0">
            <div className="size-10 rounded-xl bg-white/15 backdrop-blur flex items-center justify-center shrink-0">
              <Newspaper className="size-5" />
            </div>
            <div className="space-y-1 min-w-0 flex-1">
              <div className="page-title-kicker opacity-80">NEWS FEED</div>
              <div className="flex items-center gap-2 flex-wrap">
                <h1 className="page-title-main">新闻资讯</h1>
                <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${dataSource === 'api' ? 'bg-white/25' : 'bg-white/15'}`}>
                  {dataSource === 'api' ? '实时聚合' : '本地资讯'}
                </span>
              </div>
              <p className="page-title-sub flex items-center gap-1">
                <Calendar className="size-3" />
                今日资讯 · {getUpdateLabel(today)}
                {updateTime && dataSource === 'api' && (
                  <>
                    <span className="opacity-50">·</span>
                    <span>上次更新 {updateTime}</span>
                  </>
                )}
              </p>
            </div>
          </div>

          {/* 海关要闻速览 */}
          {customsNews.length > 0 && (
            <div className="mt-4 pt-4 border-t border-white/20">
              <div className="text-xs font-semibold mb-2 opacity-90">
                📦 今日海关要闻
              </div>
              <div className="space-y-1.5">
                 {customsNews.slice(0, 6).map((n) => (
                  <div key={n.id} className="text-sm flex items-start gap-2">
                    <span className="shrink-0">{n.flag}</span>
                    <span className="line-clamp-1 opacity-95">{n.title}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </CollapsibleSection>

      {/* Country Tabs + News List */}
      <CollapsibleSection
        title="资讯列表"
        subtitle={`${filteredNews.length} 条 · 按国家筛选`}
        summary="全球跨境资讯一站速览"
        badge={`${filteredNews.length} 条`}
        badgeColor="info"
        theme={theme}
        expanded={expandedId === 'list'}
        onToggle={() => toggleSection('list')}
        icon={<Clock className="size-5" />}
      >
        <Tabs defaultValue="all" onValueChange={setActiveCountry}>
          <TabsList className="w-full h-auto py-1 overflow-x-auto flex flex-nowrap">
            {COUNTRIES.map((c) => (
                <TabsTrigger key={c.key} value={c.key} className="text-xs py-1.5 shrink-0">
                  {c.flag} {c.label}
                </TabsTrigger>
            ))}
          </TabsList>

          <TabsContent value={activeCountry} className="mt-4 space-y-3">
            {filteredNews.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground text-sm">
                暂无新闻
              </div>
            ) : (
              filteredNews.map((news) => (
                <NewsCard key={news.id} news={news} theme={theme} />
              ))
            )}
          </TabsContent>
        </Tabs>
      </CollapsibleSection>
    </div>
  );
}

function NewsCard({ news, theme }: { news: NewsWithRelTime & { isFallback?: boolean }; theme: ThemeConfig }) {
  return (
    <Card
      className="border-0 hover:shadow-md transition-shadow"
      style={{
        backgroundColor: theme.ui.glassBg,
        backdropFilter: 'blur(10px) saturate(180%)',
        WebkitBackdropFilter: 'blur(10px) saturate(180%)',
        boxShadow: theme.ui.glassShadow,
        border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
      }}
    >
      <CardContent className="p-4">
        <div className="flex items-start gap-3">
          <div className="text-2xl shrink-0">{news.flag}</div>
          <div className="flex-1 min-w-0">
            <div className="flex items-start gap-2 mb-1.5">
              <h3 className="font-semibold text-sm leading-snug flex-1">
                {news.title}
              </h3>
            </div>

            <div className="flex items-center gap-2 mb-2 flex-wrap">
              <Badge variant="outline" className="text-xs">
                {news.country}
              </Badge>
              {news.tag && (
                <Badge className={`text-xs border-0 bg-blue-100 text-blue-700`}>
                  {news.tag}
                </Badge>
              )}
              {news.isFallback && (
                <Badge variant="outline" className="text-xs border-amber-300 text-amber-600">
                  本地预置
                </Badge>
              )}
               <span className="text-xs text-muted-foreground flex items-center gap-1">
                  <Clock className="size-3" />
                  {news.relTime}
                </span>
            </div>

            <p className="text-sm text-muted-foreground line-clamp-2 leading-relaxed">
              {news.summary}
            </p>

            <div className="mt-2 text-xs text-muted-foreground">
               来源：{news.source || '跨境资讯'}
             </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}
